import {
  ChangeDetectionStrategy,
  Component,
  computed,
  effect,
  inject,
  signal
} from '@angular/core';
import { CustomService } from '@clinicaloffice/mpage-developer';
import { FormsModule } from '@angular/forms';
import { ServiceRequestConfig } from './models/service-request-config';
import { RequestHistoryItem } from './models/request-history';
import { RequestHistoryService } from './services/request-history.service';
import { REQUEST_CONFIGS, getConfigByRequestType } from './configs/mha-pds-service.config';
import { parseGenericResponse } from './parsers/response-parsers';
import { CclServiceWrapperService } from '../services/ccl-service-wrapper.service';
import { AppStatusService } from '../services/app-status.service';
import { MockCclService } from '../services/mock-ccl.service';

/**
 * Component to test CCL service requests with comprehensive testing interface
 * Provides developer-friendly way to test gbin_mha_pds_service backend requests
 *
 * Supports both online and offline modes:
 * - Online mode: Uses live CustomService to execute CCL scripts
 * - Offline mode: Uses mock responses for development without network access
 */
@Component({
  selector: 'app-ccl-test',
  imports: [FormsModule],
  templateUrl: './ccl-test.html',
  styleUrl: './ccl-test.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class CclTest {
  private realService = inject(CustomService);
  private mockService = inject(MockCclService);
  private wrapperService = inject(CclServiceWrapperService);
  private historyService = inject(RequestHistoryService);
  private appStatus = inject(AppStatusService);

  /**
   * Manual toggle for offline mode testing
   * UI toggle allows developers to test both modes without restarting the app
   * When true, forces use of MockCclService regardless of app-level offline mode
   * When false, uses live CustomService regardless of app-level offline mode
   */
  useOfflineMode = signal<boolean>(false);
  private manualOverrideActive = signal<boolean>(false);

  /**
   * Read-only signal for current offline mode status (app-level auto-detection)
   */
  readonly isOfflineMode = computed(() => this.appStatus.offlineMode());

  /**
   * Active service based on manual toggle
   * When toggle is ON: Uses MockCclService directly (bypasses wrapper and app-level detection)
   * When toggle is OFF: Uses CustomService directly (bypasses wrapper and app-level detection)
   * This ensures the manual toggle provides a true override of automatic detection
   */
  private get activeService() {
    return this.useOfflineMode() ? this.mockService : this.realService;
  }

  // Available request configurations
  readonly REQUEST_CONFIGS = REQUEST_CONFIGS;

  // Expose Object for template
  readonly Object = Object;

  // Request configuration state
  selectedRequestType = signal<string>('getMHAPDSConfiguration');
  selectedConfig = computed(() => getConfigByRequestType(this.selectedRequestType()));
  inputMode = signal<'example' | 'custom'>('example');
  customInputData = signal<string>('');
  formInputs = signal<Record<string, any>>({});

  // Execution state
  loading = signal<boolean>(false);
  error = signal<string | null>(null);

  // Response state
  rawResponse = signal<any>(null);
  responseViewMode = signal<'raw' | 'formatted' | 'parsed'>('formatted');
  parsedResponse = computed(() => {
    const response = this.rawResponse();
    const config = this.selectedConfig();

    if (!response || !config) {
      return null;
    }

    // Use custom parser if available, otherwise use generic
    const parser = config.responseParser || parseGenericResponse;
    try {
      return parser(response);
    } catch (e) {
      console.error('Error parsing response:', e);
      return parseGenericResponse(response);
    }
  });

  // History state
  requestHistory = signal<RequestHistoryItem[]>([]);
  selectedHistoryItem = signal<RequestHistoryItem | null>(null);

  constructor() {
    // Load history on init
    this.requestHistory.set(this.historyService.loadHistory());

    // Auto-save history when it changes
    effect(() => {
      const history = this.requestHistory();
      if (history.length > 0) {
        this.historyService.saveHistory(history);
      }
    });

    effect(() => {
      const appOffline = this.appStatus.offlineMode();
      const manualOverride = this.manualOverrideActive();

      if (manualOverride) {
        console.log('[CclTest] Manual override active - keeping developer-selected mode:', this.useOfflineMode());
        return;
      }

      this.useOfflineMode.set(appOffline);
      console.log(`[CclTest] Synced manual toggle with app-level offline mode: ${appOffline}`);
    });
  }

  /**
   * Handle request type selection change
   */
  onRequestTypeChange(): void {
    const config = this.selectedConfig();
    if (config) {
      // Reset input data when switching request types
      this.customInputData.set(config.exampleData || '');
      this.formInputs.set({});

      // Initialize form inputs with default values if schema exists
      if (config.inputSchema) {
        const defaults: Record<string, any> = {};
        config.inputSchema.forEach(field => {
          defaults[field.name] = field.defaultValue || '';
        });
        this.formInputs.set(defaults);
      }
    }

    // Clear previous response and error
    this.rawResponse.set(null);
    this.error.set(null);
  }

  /**
   * Switch input mode
   */
  setInputMode(mode: 'example' | 'custom'): void {
    this.inputMode.set(mode);
  }

  /**
   * Switch response view mode
   */
  setResponseViewMode(mode: 'raw' | 'formatted' | 'parsed'): void {
    this.responseViewMode.set(mode);
  }

  /**
   * Build request data based on current input mode
   */
  private buildRequestData(): string {
    const mode = this.inputMode();
    const config = this.selectedConfig();

    if (mode === 'example') {
      return this.customInputData() || config?.exampleData || '';
    } else {
      // Custom mode
      if (config?.inputSchema && config.inputSchema.length > 0) {
        // Build JSON from form inputs
        try {
          const formData = this.formInputs();
          // If wrapperKey is specified, wrap the data for CCL cnvtjsontorec
          if (config.wrapperKey) {
            return JSON.stringify({ [config.wrapperKey]: formData });
          }
          return JSON.stringify(formData);
        } catch (e) {
          throw new Error('Failed to build JSON from form inputs');
        }
      } else {
        // Use textarea content
        const data = this.customInputData();
        if (data.trim()) {
          // Validate JSON
          try {
            JSON.parse(data);
            return data;
          } catch (e) {
            throw new Error('Invalid JSON in custom input');
          }
        }
        return '';
      }
    }
  }

  /**
   * Execute the selected service request
   */
  executeRequest(): void {
    const config = this.selectedConfig();
    if (!config) {
      this.error.set('No request type selected');
      return;
    }

    this.loading.set(true);
    this.error.set(null);
    this.rawResponse.set(null);

    const startTime = Date.now();
    const requestId = config.requestType;

    try {
      const requestData = this.buildRequestData();

      // Execute the custom CCL script using active service
      this.activeService.load(
        {
          customScript: {
            script: [
              {
                name: 'gbin_mha_pds_service:group1',
                run: 'pre',
                id: requestId,
                reference: true,
                parameters: {
                  requestType: config.requestType,
                  requestId: Date.now(),
                  requestData: requestData
                }
              }
            ],
            clearPatientSource: true
          }
        },
        [{ personId: 0, encntrId: 0 }],
        () => {
          // Callback executed when script completes
          const endTime = Date.now();
          const elapsedSeconds = Math.round((endTime - startTime) / 1000);
          const response = this.activeService.get(requestId);

          if (response) {
            if (response.error) {
              this.error.set(response.error);
              this.addToHistory({
                id: crypto.randomUUID(),
                timestamp: startTime,
                requestType: config.requestType,
                requestData: requestData,
                response: response,
                status: 'error',
                errorMessage: response.error,
                elapsedTimeSeconds: elapsedSeconds
              });
            } else {
              this.rawResponse.set(response);
              this.addToHistory({
                id: crypto.randomUUID(),
                timestamp: startTime,
                requestType: config.requestType,
                requestData: requestData,
                response: response,
                status: 'success',
                elapsedTimeSeconds: elapsedSeconds
              });
              // Default to formatted view after successful execution
              this.responseViewMode.set('formatted');
            }
          } else {
            const errorMsg = 'No response from CCL script';
            this.error.set(errorMsg);
            this.addToHistory({
              id: crypto.randomUUID(),
              timestamp: startTime,
              requestType: config.requestType,
              requestData: requestData,
              response: null,
              status: 'error',
              errorMessage: errorMsg,
              elapsedTimeSeconds: elapsedSeconds
            });
          }

          this.loading.set(false);
        }
      );
    } catch (e) {
      const errorMsg = e instanceof Error ? e.message : 'Unknown error occurred';
      this.error.set(errorMsg);
      this.loading.set(false);

      this.addToHistory({
        id: crypto.randomUUID(),
        timestamp: startTime,
        requestType: config.requestType,
        requestData: '',
        response: null,
        status: 'error',
        errorMessage: errorMsg,
        elapsedTimeSeconds: 0
      });
    }
  }

  /**
   * Add item to history
   */
  private addToHistory(item: RequestHistoryItem): void {
    const updatedHistory = this.historyService.addHistoryItem(item);
    this.requestHistory.set(updatedHistory);
  }

  /**
   * Load a history item
   */
  loadHistoryItem(item: RequestHistoryItem): void {
    this.selectedHistoryItem.set(item);
    this.selectedRequestType.set(item.requestType);

    // Set input data
    this.customInputData.set(item.requestData);

    // Set response
    this.rawResponse.set(item.response);
    this.error.set(item.errorMessage || null);

    // Switch to formatted view
    this.responseViewMode.set('formatted');
  }

  /**
   * Clear all history
   */
  clearHistory(): void {
    this.historyService.clearHistory();
    this.requestHistory.set([]);
    this.selectedHistoryItem.set(null);
  }

  /**
   * Remove a single history item
   */
  removeHistoryItem(id: string, event: Event): void {
    event.stopPropagation(); // Prevent loading the item when clicking delete
    const updatedHistory = this.historyService.removeHistoryItem(id);
    this.requestHistory.set(updatedHistory);

    // Clear selected item if it was deleted
    if (this.selectedHistoryItem()?.id === id) {
      this.selectedHistoryItem.set(null);
    }
  }

  /**
   * Clear current results
   */
  clearResults(): void {
    this.rawResponse.set(null);
    this.error.set(null);
    this.selectedHistoryItem.set(null);
  }

  /**
   * Reset form to defaults
   */
  resetForm(): void {
    const config = this.selectedConfig();
    if (config) {
      this.customInputData.set(config.exampleData || '');

      if (config.inputSchema) {
        const defaults: Record<string, any> = {};
        config.inputSchema.forEach(field => {
          defaults[field.name] = field.defaultValue || '';
        });
        this.formInputs.set(defaults);
      }
    }
    this.inputMode.set('example');
    this.clearResults();
  }

  /**
   * Format timestamp for display
   */
  formatTimestamp(timestamp: number): string {
    return new Date(timestamp).toLocaleString();
  }

  /**
   * Get formatted JSON string
   */
  getFormattedJson(obj: any): string {
    try {
      return JSON.stringify(obj, null, 2);
    } catch (e) {
      return 'Error formatting JSON';
    }
  }

  /**
   * Get raw JSON string
   */
  getRawJson(obj: any): string {
    try {
      return JSON.stringify(obj);
    } catch (e) {
      return 'Error converting to JSON';
    }
  }

  /**
   * Toggle offline mode for testing
   * This provides a manual override that bypasses app-level automatic detection
   */
  toggleOfflineMode(): void {
    const currentValue = this.useOfflineMode();
    const newValue = !currentValue;
    console.log(`[CclTest] toggleOfflineMode() - Current: ${currentValue}, New: ${newValue}`);
    this.useOfflineMode.set(newValue);
    const appOffline = this.appStatus.offlineMode();
    const overrideActive = newValue !== appOffline;
    this.manualOverrideActive.set(overrideActive);
    console.log(
      overrideActive
        ? '[CclTest] Manual offline override enabled - diverging from app-level status'
        : '[CclTest] Manual offline override cleared - re-syncing with app-level status'
    );
    console.log(newValue ? '[CclTest] Manual offline mode enabled - Will use MockCclService directly' : '[CclTest] Manual offline mode disabled - Will use live CustomService directly');
    console.log(`[CclTest] App-level offline mode status (read-only, not affecting manual toggle): ${this.isOfflineMode()}`);
  }
}
