/**
 * Get configuration by request type
 */
export function getConfigByRequestType(requestType: string): ServiceRequestConfig | undefined {
  return REQUEST_CONFIGS.find(config => config.requestType === requestType);
}

/**
 * Get all request types grouped by category
 */
export function getConfigsByCategory(): Map<string, ServiceRequestConfig[]> {
  const grouped = new Map<string, ServiceRequestConfig[]>();

  REQUEST_CONFIGS.forEach(config => {
    const existing = grouped.get(config.category) || [];
    existing.push(config);
    grouped.set(config.category, existing);
  });

  return grouped;
}
