import { Injectable } from '@angular/core';
import { RequestHistoryItem } from '../models/request-history';

/**
 * Service to manage request history in localStorage
 */
@Injectable({
  providedIn: 'root'
})
export class RequestHistoryService {
  private readonly HISTORY_KEY = 'mha_pds_service_test_history';
  private readonly FORM_STATE_KEY = 'mha_pds_service_test_form_state';
  private readonly MAX_HISTORY_ITEMS = 50;

  /**
   * Load request history from localStorage
   */
  loadHistory(): RequestHistoryItem[] {
    try {
      const stored = localStorage.getItem(this.HISTORY_KEY);
      if (!stored) {
        return [];
      }
      return JSON.parse(stored) as RequestHistoryItem[];
    } catch (error) {
      console.error('Error loading history from localStorage:', error);
      return [];
    }
  }

  /**
   * Save request history to localStorage
   */
  saveHistory(history: RequestHistoryItem[]): void {
    try {
      // Keep only the most recent MAX_HISTORY_ITEMS
      const trimmedHistory = history.slice(0, this.MAX_HISTORY_ITEMS);
      localStorage.setItem(this.HISTORY_KEY, JSON.stringify(trimmedHistory));
    } catch (error) {
      console.error('Error saving history to localStorage:', error);
      // Handle quota exceeded errors gracefully
      if (error instanceof Error && error.name === 'QuotaExceededError') {
        // Try to save with fewer items
        try {
          const reducedHistory = history.slice(0, 10);
          localStorage.setItem(this.HISTORY_KEY, JSON.stringify(reducedHistory));
        } catch (retryError) {
          console.error('Failed to save even reduced history:', retryError);
        }
      }
    }
  }

  /**
   * Add a new item to history
   */
  addHistoryItem(item: RequestHistoryItem): RequestHistoryItem[] {
    const history = this.loadHistory();
    history.unshift(item); // Add to beginning
    this.saveHistory(history);
    return history;
  }

  /**
   * Clear all history
   */
  clearHistory(): void {
    try {
      localStorage.removeItem(this.HISTORY_KEY);
    } catch (error) {
      console.error('Error clearing history:', error);
    }
  }

  /**
   * Remove a single history item by id
   */
  removeHistoryItem(id: string): RequestHistoryItem[] {
    const history = this.loadHistory();
    const filtered = history.filter(item => item.id !== id);
    this.saveHistory(filtered);
    return filtered;
  }

  /**
   * Load form state from localStorage
   */
  loadFormState(): any {
    try {
      const stored = localStorage.getItem(this.FORM_STATE_KEY);
      if (!stored) {
        return null;
      }
      return JSON.parse(stored);
    } catch (error) {
      console.error('Error loading form state from localStorage:', error);
      return null;
    }
  }

  /**
   * Save form state to localStorage
   */
  saveFormState(state: any): void {
    try {
      localStorage.setItem(this.FORM_STATE_KEY, JSON.stringify(state));
    } catch (error) {
      console.error('Error saving form state to localStorage:', error);
    }
  }

  /**
   * Clear form state
   */
  clearFormState(): void {
    try {
      localStorage.removeItem(this.FORM_STATE_KEY);
    } catch (error) {
      console.error('Error clearing form state:', error);
    }
  }
}
